from collections import deque

def comps(M):
 m,n=M.shape; seen=set(); out=[]
 for r in range(m):
  for c in range(n):
   if M[r,c]!=7 and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c)); cells=[]
    while q:
     x,y=q.pop();cells.append((x,y))
     for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
      p=(x+dx,y+dy)
      if 0<=p[0]<m and 0<=p[1]<n and M[p]!=7 and p not in seen: seen.add(p);q.append(p)
    rs=[x for x,y in cells];cs=[y for x,y in cells];
    out.append((min(rs),max(rs),min(cs),max(cs),len(cells),{int(M[p]) for p in cells},cells))
 return out
